#include "http.h"

#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <sys/uio.h>
#include <unistd.h>

/* ---------- buffered reader over the bytes that followed the head ---------- */

typedef struct {
    int fd;
    size_t pos, len;
    unsigned char buf[HTTP_HEAD_MAX];
} reader;

/* Returns >0 bytes read, 0 on EOF, -1 on error/timeout. */
static ssize_t recv_some(int fd, void *buf, size_t cap)
{
    for (;;) {
        ssize_t n = recv(fd, buf, cap, 0);
        if (n >= 0 || errno != EINTR)
            return n;
    }
}

static int reader_fill(reader *r)
{
    if (r->pos < r->len)
        return 0;
    ssize_t n = recv_some(r->fd, r->buf, sizeof r->buf);
    if (n <= 0)
        return -1;
    r->pos = 0;
    r->len = (size_t)n;
    return 0;
}

static int reader_exact(reader *r, unsigned char *dst, size_t n)
{
    /* Drain buffered bytes first, then read large bodies straight into dst. */
    size_t avail = r->len - r->pos;
    size_t take = avail < n ? avail : n;
    memcpy(dst, r->buf + r->pos, take);
    r->pos += take;
    dst += take;
    n -= take;
    while (n > 0) {
        ssize_t got = recv_some(r->fd, dst, n);
        if (got <= 0)
            return -1;
        dst += got;
        n -= (size_t)got;
    }
    return 0;
}

/* Reads a line terminated by LF (CR stripped) into out, NUL-terminated.
 * Returns length, -1 on I/O failure, -2 if the line exceeds cap-1. */
static ssize_t reader_line(reader *r, char *out, size_t cap)
{
    size_t n = 0;
    for (;;) {
        if (reader_fill(r) != 0)
            return -1;
        unsigned char c = r->buf[r->pos++];
        if (c == '\n')
            break;
        if (n + 1 >= cap)
            return -2;
        out[n++] = (char)c;
    }
    if (n > 0 && out[n - 1] == '\r')
        n--;
    out[n] = '\0';
    return (ssize_t)n;
}

/* ---------- parsing helpers ---------- */

static bool is_tchar(unsigned char c)
{
    if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'))
        return true;
    return c != '\0' && strchr("!#$%&'*+-.^_`|~", c) != NULL;
}

/* Parses a non-empty decimal number; returns false on garbage or overflow. */
static bool parse_size(const char *s, size_t *out)
{
    if (!*s)
        return false;
    uint64_t v = 0;
    for (; *s; s++) {
        if (*s < '0' || *s > '9')
            return false;
        if (v > (UINT64_MAX - 9) / 10)
            return false;
        v = v * 10 + (uint64_t)(*s - '0');
    }
    if (v > SIZE_MAX)
        return false;
    *out = (size_t)v;
    return true;
}

static char *trim(char *s)
{
    while (*s == ' ' || *s == '\t')
        s++;
    char *end = s + strlen(s);
    while (end > s && (end[-1] == ' ' || end[-1] == '\t'))
        *--end = '\0';
    return s;
}

/* Finds the end of the header block; returns offset past the blank line. */
static size_t find_head_end(const char *buf, size_t len)
{
    for (size_t i = 0; i + 1 < len; i++) {
        if (buf[i] != '\n')
            continue;
        if (buf[i + 1] == '\n')
            return i + 2;
        if (i + 2 < len && buf[i + 1] == '\r' && buf[i + 2] == '\n')
            return i + 3;
    }
    return 0;
}

/* Splits off the next line in place; returns NULL when exhausted. */
static char *next_line(char **cursor)
{
    char *s = *cursor;
    char *nl = strchr(s, '\n');
    if (!nl)
        return NULL;
    *nl = '\0';
    if (nl > s && nl[-1] == '\r')
        nl[-1] = '\0';
    *cursor = nl + 1;
    return s;
}

typedef struct {
    bool has_length;
    size_t length;
    bool chunked;
    bool expect_continue;
} body_info;

static int parse_head(http_request *req, body_info *bi)
{
    char *cursor = req->head;
    char *line = next_line(&cursor);
    if (!line)
        return 400;

    /* Request line: method SP target SP HTTP/1.x */
    char *sp1 = strchr(line, ' ');
    if (!sp1)
        return 400;
    *sp1 = '\0';
    char *target = sp1 + 1;
    char *sp2 = strchr(target, ' ');
    if (!sp2)
        return 400;
    *sp2 = '\0';
    const char *version = sp2 + 1;

    if (!*line || !*target)
        return 400;
    for (const char *p = line; *p; p++)
        if (!is_tchar((unsigned char)*p))
            return 400;
    if (strncmp(version, "HTTP/1.", 7) != 0 || version[7] < '0' || version[7] > '9' || version[8])
        return strncmp(version, "HTTP/", 5) == 0 ? 505 : 400;
    req->method = line;
    req->target = target;

    while ((line = next_line(&cursor)) != NULL && *line) {
        char *colon = strchr(line, ':');
        if (!colon || colon == line)
            return 400;
        *colon = '\0';
        for (const char *p = line; *p; p++)
            if (!is_tchar((unsigned char)*p))
                return 400;
        char *value = trim(colon + 1);

        if (strcasecmp(line, "Content-Length") == 0) {
            size_t n;
            if (!parse_size(value, &n))
                return 400;
            if (bi->has_length && bi->length != n)
                return 400;
            bi->has_length = true;
            bi->length = n;
        } else if (strcasecmp(line, "Transfer-Encoding") == 0) {
            if (strcasecmp(value, "chunked") != 0)
                return 501;
            bi->chunked = true;
        } else if (strcasecmp(line, "Expect") == 0) {
            if (strcasecmp(value, "100-continue") != 0)
                return 417;
            bi->expect_continue = true;
        }
    }
    if (bi->chunked && bi->has_length)
        return 400;
    return 0;
}

static int send_all(int fd, const void *buf, size_t len)
{
    const char *p = buf;
    while (len > 0) {
        ssize_t n = send(fd, p, len, 0);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            return -1;
        }
        p += n;
        len -= (size_t)n;
    }
    return 0;
}

static int read_chunked(reader *r, http_request *req, size_t max_body)
{
    char line[256];
    size_t cap = 0;
    for (;;) {
        ssize_t n = reader_line(r, line, sizeof line);
        if (n == -1)
            return -1;
        if (n == -2)
            return 400;
        char *ext = strchr(line, ';');
        if (ext)
            *ext = '\0';
        char *hex = trim(line);
        if (!*hex)
            return 400;
        size_t size = 0;
        for (const char *p = hex; *p; p++) {
            int d;
            if (*p >= '0' && *p <= '9')
                d = *p - '0';
            else if (*p >= 'a' && *p <= 'f')
                d = *p - 'a' + 10;
            else if (*p >= 'A' && *p <= 'F')
                d = *p - 'A' + 10;
            else
                return 400;
            if (size > (SIZE_MAX >> 4))
                return 413;
            size = (size << 4) | (size_t)d;
        }
        if (size == 0)
            break;
        if (size > max_body - req->body_len)
            return 413;

        size_t need = req->body_len + size;
        if (need > cap) {
            size_t ncap = cap ? cap : 4096;
            while (ncap < need)
                ncap *= 2;
            if (ncap > max_body)
                ncap = max_body;
            unsigned char *nb = realloc(req->body, ncap);
            if (!nb)
                return 500;
            req->body = nb;
            cap = ncap;
        }
        if (reader_exact(r, req->body + req->body_len, size) != 0)
            return -1;
        req->body_len += size;

        n = reader_line(r, line, sizeof line);
        if (n == -1)
            return -1;
        if (n != 0)
            return 400;
    }
    /* Trailer section: skip until the blank line. */
    for (;;) {
        ssize_t n = reader_line(r, line, sizeof line);
        if (n == -1)
            return -1;
        if (n == 0)
            break;
    }
    return 0;
}

int http_read_request(int fd, http_request *req, size_t max_body)
{
    req->method = NULL;
    req->target = NULL;
    req->body = NULL;
    req->body_len = 0;

    size_t filled = 0, head_end = 0;
    while (!(head_end = find_head_end(req->head, filled))) {
        if (filled == HTTP_HEAD_MAX)
            return 431;
        ssize_t n = recv_some(fd, req->head + filled, HTTP_HEAD_MAX - filled);
        if (n <= 0)
            return -1;
        filled += (size_t)n;
        req->head[filled] = '\0';
    }

    reader *r = malloc(sizeof *r);
    if (!r)
        return 500;
    r->fd = fd;
    r->pos = 0;
    r->len = filled - head_end;
    memcpy(r->buf, req->head + head_end, r->len);
    req->head[head_end] = '\0';

    body_info bi = {0};
    int rc = parse_head(req, &bi);
    if (rc != 0)
        goto out;

    if (bi.has_length && bi.length > max_body) {
        rc = 413;
        goto out;
    }
    if (bi.expect_continue && (bi.chunked || bi.length > 0)) {
        static const char cont[] = "HTTP/1.1 100 Continue\r\n\r\n";
        if (send_all(fd, cont, sizeof cont - 1) != 0) {
            rc = -1;
            goto out;
        }
    }

    if (bi.chunked) {
        rc = read_chunked(r, req, max_body);
    } else if (bi.length > 0) {
        req->body = malloc(bi.length);
        if (!req->body) {
            rc = 500;
            goto out;
        }
        if (reader_exact(r, req->body, bi.length) != 0)
            rc = -1;
        else
            req->body_len = bi.length;
    }

out:
    free(r);
    return rc;
}

void http_request_cleanup(http_request *req)
{
    free(req->body);
    req->body = NULL;
    req->body_len = 0;
}

static const char *reason(int status)
{
    switch (status) {
    case 100: return "Continue";
    case 200: return "OK";
    case 201: return "Created";
    case 204: return "No Content";
    case 400: return "Bad Request";
    case 404: return "Not Found";
    case 405: return "Method Not Allowed";
    case 413: return "Content Too Large";
    case 417: return "Expectation Failed";
    case 431: return "Request Header Fields Too Large";
    case 500: return "Internal Server Error";
    case 501: return "Not Implemented";
    case 505: return "HTTP Version Not Supported";
    default: return "Unknown";
    }
}

int http_send(int fd, int status, const char *content_type, const void *body, size_t len)
{
    char head[256];
    int n;
    if (content_type)
        n = snprintf(head, sizeof head,
                     "HTTP/1.1 %d %s\r\nContent-Type: %s\r\nContent-Length: %zu\r\nConnection: close\r\n\r\n",
                     status, reason(status), content_type, len);
    else
        n = snprintf(head, sizeof head,
                     "HTTP/1.1 %d %s\r\nContent-Length: %zu\r\nConnection: close\r\n\r\n",
                     status, reason(status), len);
    if (n < 0 || (size_t)n >= sizeof head)
        return -1;

    /* Send head and body together to avoid an extra small packet. */
    struct iovec iov[2] = {
        {.iov_base = head, .iov_len = (size_t)n},
        {.iov_base = (void *)body, .iov_len = body ? len : 0},
    };
    int iovcnt = 2;
    struct iovec *v = iov;
    while (iovcnt > 0) {
        ssize_t w = writev(fd, v, iovcnt);
        if (w < 0) {
            if (errno == EINTR)
                continue;
            return -1;
        }
        size_t done = (size_t)w;
        while (iovcnt > 0 && done >= v->iov_len) {
            done -= v->iov_len;
            v++;
            iovcnt--;
        }
        if (iovcnt > 0) {
            v->iov_base = (char *)v->iov_base + done;
            v->iov_len -= done;
        }
    }
    return 0;
}

/* Minimal HTTP/1.1 request parsing and response writing over a socket. */
#ifndef KVHTTP_HTTP_H
#define KVHTTP_HTTP_H

#include <stddef.h>

#define HTTP_HEAD_MAX (16 * 1024)

typedef struct {
    /* Request line pieces point into `head` and are NUL-terminated. */
    char *method;
    char *target;
    unsigned char *body; /* malloc'd, NULL when the request has no body */
    size_t body_len;
    char head[HTTP_HEAD_MAX + 1];
} http_request;

/* Reads one request from `fd`, accepting bodies up to `max_body` bytes.
 * Returns 0 on success; a 4xx/5xx status code when the request is
 * malformed and should be answered with that status; or -1 when the peer
 * went away or timed out and no response should be attempted.
 * On every return, http_request_cleanup must be called. */
int http_read_request(int fd, http_request *req, size_t max_body);
void http_request_cleanup(http_request *req);

/* Writes a complete response with Content-Length and Connection: close.
 * `content_type` may be NULL. Returns 0 on success, -1 on I/O error. */
int http_send(int fd, int status, const char *content_type, const void *body, size_t len);

#endif

/* kvhttp: an HTTP/1.1 in-memory key-value server.
 * Usage: ./app <port>  (listens on 127.0.0.1) */
#include "http.h"
#include "store.h"

#include <arpa/inet.h>
#include <errno.h>
#include <netinet/in.h>
#include <netinet/tcp.h>
#include <pthread.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <unistd.h>

#define MAX_VALUE (1024 * 1024)
#define IO_TIMEOUT_SEC 30
#define LINGER_TIMEOUT_MS 500
#define THREAD_STACK (256 * 1024)

static store *g_store;

/* ---------- routing ---------- */

static bool valid_key(const char *k)
{
    size_t n = 0;
    for (; k[n]; n++) {
        unsigned char c = (unsigned char)k[n];
        bool ok = (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') ||
                  c == '_' || c == '-';
        if (!ok || n >= STORE_KEY_MAX)
            return false;
    }
    return n > 0;
}

static int send_empty(int fd, int status) { return http_send(fd, status, NULL, NULL, 0); }

static void handle_list(int fd)
{
    size_t count = 0;
    char **keys = store_keys(g_store, &count);
    if (!keys) {
        send_empty(fd, 500);
        return;
    }
    /* Keys are restricted to [A-Za-z0-9_-], so no JSON escaping is needed. */
    size_t len = 2;
    for (size_t i = 0; i < count; i++)
        len += strlen(keys[i]) + 3;
    char *json = malloc(len + 1);
    if (!json) {
        store_keys_free(keys, count);
        send_empty(fd, 500);
        return;
    }
    char *p = json;
    *p++ = '[';
    for (size_t i = 0; i < count; i++) {
        if (i)
            *p++ = ',';
        *p++ = '"';
        size_t kl = strlen(keys[i]);
        memcpy(p, keys[i], kl);
        p += kl;
        *p++ = '"';
    }
    *p++ = ']';
    store_keys_free(keys, count);
    http_send(fd, 200, "application/json", json, (size_t)(p - json));
    free(json);
}

static void handle_key(int fd, const http_request *req, const char *key)
{
    const char *m = req->method;
    if (strcmp(m, "GET") == 0) {
        blob *b = store_get(g_store, key);
        if (!b) {
            send_empty(fd, 404);
            return;
        }
        http_send(fd, 200, "application/octet-stream", blob_data(b), blob_len(b));
        blob_release(b);
    } else if (strcmp(m, "PUT") == 0) {
        switch (store_put(g_store, key, req->body, req->body_len)) {
        case STORE_CREATED: send_empty(fd, 201); break;
        case STORE_OK: send_empty(fd, 200); break;
        case STORE_NOMEM: send_empty(fd, 500); break;
        }
    } else if (strcmp(m, "DELETE") == 0) {
        send_empty(fd, store_delete(g_store, key) ? 204 : 404);
    } else {
        send_empty(fd, 405);
    }
}

static void route(int fd, const http_request *req)
{
    const char *path = req->target;
    const char *m = req->method;

    if (strcmp(path, "/health") == 0) {
        if (strcmp(m, "GET") == 0)
            http_send(fd, 200, "text/plain", "ok", 2);
        else
            send_empty(fd, 405);
    } else if (strcmp(path, "/kv") == 0) {
        if (strcmp(m, "GET") == 0)
            handle_list(fd);
        else
            send_empty(fd, 405);
    } else if (strncmp(path, "/kv/", 4) == 0) {
        const char *key = path + 4;
        if (!valid_key(key))
            send_empty(fd, 400);
        else
            handle_key(fd, req, key);
    } else {
        send_empty(fd, 404);
    }
}

/* ---------- connection handling ---------- */

/* Half-close and drain so any unread request bytes do not turn our close
 * into a RST that could destroy the response before the client reads it. */
static void lingering_close(int fd)
{
    shutdown(fd, SHUT_WR);
    struct timeval tv = {.tv_sec = 0, .tv_usec = LINGER_TIMEOUT_MS * 1000};
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof tv);
    char sink[4096];
    size_t total = 0;
    while (total < 4 * MAX_VALUE) {
        ssize_t n = recv(fd, sink, sizeof sink, 0);
        if (n < 0 && errno == EINTR)
            continue;
        if (n <= 0)
            break;
        total += (size_t)n;
    }
    close(fd);
}

static void *connection_main(void *arg)
{
    int fd = (int)(intptr_t)arg;

    http_request *req = malloc(sizeof *req);
    if (!req) {
        send_empty(fd, 500);
        lingering_close(fd);
        return NULL;
    }
    int rc = http_read_request(fd, req, MAX_VALUE);
    if (rc == 0)
        route(fd, req);
    else if (rc > 0)
        send_empty(fd, rc);
    http_request_cleanup(req);
    free(req);

    if (rc < 0)
        close(fd);
    else
        lingering_close(fd);
    return NULL;
}

static void configure_client(int fd)
{
    struct timeval tv = {.tv_sec = IO_TIMEOUT_SEC, .tv_usec = 0};
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof tv);
    setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof tv);
    int one = 1;
    setsockopt(fd, IPPROTO_TCP, TCP_NODELAY, &one, sizeof one);
#ifdef SO_NOSIGPIPE
    setsockopt(fd, SOL_SOCKET, SO_NOSIGPIPE, &one, sizeof one);
#endif
}

static int listen_on(unsigned short port)
{
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket");
        return -1;
    }
    int one = 1;
    setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    if (bind(fd, (struct sockaddr *)&addr, sizeof addr) != 0) {
        perror("bind");
        close(fd);
        return -1;
    }
    if (listen(fd, SOMAXCONN) != 0) {
        perror("listen");
        close(fd);
        return -1;
    }
    return fd;
}

static bool parse_port(const char *s, unsigned short *out)
{
    char *end;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno || end == s || *end || v < 1 || v > 65535)
        return false;
    *out = (unsigned short)v;
    return true;
}

int main(int argc, char **argv)
{
    unsigned short port;
    if (argc != 2 || !parse_port(argv[1], &port)) {
        fprintf(stderr, "usage: %s <port>\n", argv[0]);
        return 2;
    }
    signal(SIGPIPE, SIG_IGN);

    g_store = store_new();
    if (!g_store) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    int lfd = listen_on(port);
    if (lfd < 0)
        return 1;

    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
    pthread_attr_setstacksize(&attr, THREAD_STACK);

    for (;;) {
        int cfd = accept(lfd, NULL, NULL);
        if (cfd < 0) {
            if (errno == EINTR || errno == ECONNABORTED)
                continue;
            if (errno == EMFILE || errno == ENFILE || errno == ENOBUFS || errno == ENOMEM) {
                /* Resource exhaustion: back off briefly instead of spinning. */
                usleep(10 * 1000);
                continue;
            }
            perror("accept");
            break;
        }
        configure_client(cfd);
        pthread_t tid;
        if (pthread_create(&tid, &attr, connection_main, (void *)(intptr_t)cfd) != 0) {
            send_empty(cfd, 500);
            close(cfd);
        }
    }

    pthread_attr_destroy(&attr);
    close(lfd);
    store_free(g_store);
    return 1;
}

#include "store.h"

#include <pthread.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

struct blob {
    atomic_size_t refs;
    size_t len;
    unsigned char data[];
};

const unsigned char *blob_data(const blob *b) { return b->data; }
size_t blob_len(const blob *b) { return b->len; }

static blob *blob_new(const void *data, size_t len)
{
    blob *b = malloc(sizeof *b + len);
    if (!b)
        return NULL;
    atomic_init(&b->refs, 1);
    b->len = len;
    if (len)
        memcpy(b->data, data, len);
    return b;
}

static void blob_retain(blob *b) { atomic_fetch_add_explicit(&b->refs, 1, memory_order_relaxed); }

void blob_release(blob *b)
{
    if (b && atomic_fetch_sub_explicit(&b->refs, 1, memory_order_acq_rel) == 1)
        free(b);
}

typedef struct entry {
    struct entry *next;
    uint64_t hash;
    blob *value;
    char key[STORE_KEY_MAX + 1];
} entry;

struct store {
    pthread_rwlock_t lock;
    entry **buckets;
    size_t nbuckets; /* always a power of two */
    size_t count;
};

#define INITIAL_BUCKETS 64

static uint64_t hash_key(const char *key)
{
    uint64_t h = 1469598103934665603ULL; /* FNV-1a */
    for (const unsigned char *p = (const unsigned char *)key; *p; p++) {
        h ^= *p;
        h *= 1099511628211ULL;
    }
    return h;
}

store *store_new(void)
{
    store *s = calloc(1, sizeof *s);
    if (!s)
        return NULL;
    s->buckets = calloc(INITIAL_BUCKETS, sizeof *s->buckets);
    if (!s->buckets || pthread_rwlock_init(&s->lock, NULL) != 0) {
        free(s->buckets);
        free(s);
        return NULL;
    }
    s->nbuckets = INITIAL_BUCKETS;
    return s;
}

void store_free(store *s)
{
    if (!s)
        return;
    for (size_t i = 0; i < s->nbuckets; i++) {
        entry *e = s->buckets[i];
        while (e) {
            entry *next = e->next;
            blob_release(e->value);
            free(e);
            e = next;
        }
    }
    free(s->buckets);
    pthread_rwlock_destroy(&s->lock);
    free(s);
}

/* Caller holds the lock. */
static entry **find_slot(const store *s, const char *key, uint64_t h)
{
    entry **pp = &s->buckets[h & (s->nbuckets - 1)];
    while (*pp && ((*pp)->hash != h || strcmp((*pp)->key, key) != 0))
        pp = &(*pp)->next;
    return pp;
}

/* Caller holds the write lock. Growth failure is not fatal: the table
 * just keeps working with longer chains. */
static void maybe_grow(store *s)
{
    if (s->count * 4 < s->nbuckets * 3)
        return;
    size_t n = s->nbuckets * 2;
    entry **nb = calloc(n, sizeof *nb);
    if (!nb)
        return;
    for (size_t i = 0; i < s->nbuckets; i++) {
        entry *e = s->buckets[i];
        while (e) {
            entry *next = e->next;
            size_t idx = e->hash & (n - 1);
            e->next = nb[idx];
            nb[idx] = e;
            e = next;
        }
    }
    free(s->buckets);
    s->buckets = nb;
    s->nbuckets = n;
}

store_put_result store_put(store *s, const char *key, const void *data, size_t len)
{
    size_t klen = strlen(key);
    if (klen > STORE_KEY_MAX)
        return STORE_NOMEM;

    blob *b = blob_new(data, len);
    if (!b)
        return STORE_NOMEM;
    uint64_t h = hash_key(key);

    pthread_rwlock_wrlock(&s->lock);
    entry **pp = find_slot(s, key, h);
    if (*pp) {
        blob *old = (*pp)->value;
        (*pp)->value = b;
        pthread_rwlock_unlock(&s->lock);
        blob_release(old);
        return STORE_OK;
    }

    entry *e = malloc(sizeof *e);
    if (!e) {
        pthread_rwlock_unlock(&s->lock);
        blob_release(b);
        return STORE_NOMEM;
    }
    e->next = NULL;
    e->hash = h;
    e->value = b;
    memcpy(e->key, key, klen + 1);
    *pp = e;
    s->count++;
    maybe_grow(s);
    pthread_rwlock_unlock(&s->lock);
    return STORE_CREATED;
}

blob *store_get(store *s, const char *key)
{
    uint64_t h = hash_key(key);
    pthread_rwlock_rdlock(&s->lock);
    entry *e = *find_slot(s, key, h);
    blob *b = NULL;
    if (e) {
        b = e->value;
        blob_retain(b);
    }
    pthread_rwlock_unlock(&s->lock);
    return b;
}

bool store_delete(store *s, const char *key)
{
    uint64_t h = hash_key(key);
    pthread_rwlock_wrlock(&s->lock);
    entry **pp = find_slot(s, key, h);
    entry *e = *pp;
    if (e) {
        *pp = e->next;
        s->count--;
    }
    pthread_rwlock_unlock(&s->lock);
    if (!e)
        return false;
    blob_release(e->value);
    free(e);
    return true;
}

static int cmp_keys(const void *a, const void *b)
{
    return strcmp(*(char *const *)a, *(char *const *)b);
}

void store_keys_free(char **keys, size_t count)
{
    if (!keys)
        return;
    for (size_t i = 0; i < count; i++)
        free(keys[i]);
    free(keys);
}

char **store_keys(store *s, size_t *count)
{
    pthread_rwlock_rdlock(&s->lock);
    size_t n = s->count;
    char **keys = malloc((n ? n : 1) * sizeof *keys);
    size_t got = 0;
    if (keys) {
        for (size_t i = 0; i < s->nbuckets; i++) {
            for (entry *e = s->buckets[i]; e; e = e->next) {
                keys[got] = strdup(e->key);
                if (!keys[got]) {
                    pthread_rwlock_unlock(&s->lock);
                    store_keys_free(keys, got);
                    return NULL;
                }
                got++;
            }
        }
    }
    pthread_rwlock_unlock(&s->lock);
    if (!keys)
        return NULL;

    qsort(keys, got, sizeof *keys, cmp_keys);
    *count = got;
    return keys;
}

/* Thread-safe in-memory key-value store. */
#ifndef KVHTTP_STORE_H
#define KVHTTP_STORE_H

#include <stdbool.h>
#include <stddef.h>

#define STORE_KEY_MAX 64

/* Immutable, reference-counted value. Readers hold a reference while they
 * transmit it, so the store lock is never held during network I/O. */
typedef struct blob blob;

const unsigned char *blob_data(const blob *b);
size_t blob_len(const blob *b);
void blob_release(blob *b);

typedef struct store store;

store *store_new(void);
void store_free(store *s);

typedef enum { STORE_OK, STORE_CREATED, STORE_NOMEM } store_put_result;

/* Copies `len` bytes from `data`. Returns STORE_CREATED for a new key,
 * STORE_OK when replacing an existing value. */
store_put_result store_put(store *s, const char *key, const void *data, size_t len);

/* Returns a new reference (release with blob_release) or NULL if absent. */
blob *store_get(store *s, const char *key);

/* Returns true if the key existed and was removed. */
bool store_delete(store *s, const char *key);

/* Returns a malloc'd array of malloc'd key strings, sorted ascending by
 * byte value. Caller frees via store_keys_free. Returns NULL on OOM. */
char **store_keys(store *s, size_t *count);
void store_keys_free(char **keys, size_t count);

#endif
